using Mutagen.Bethesda.Plugins.Binary.Headers;
using Mutagen.Bethesda.Plugins.Meta;
using Mutagen.Bethesda.Starfield;
using Shouldly;
using Xunit;
using static Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield.StarfieldTestRecords;

namespace Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield;

// Three Weather subrecords were kept as raw bytes. Per xEdit (RegisterRecordDef(WTHR)) and the data:
// LNAM is the UInt32 Max Cloud Layers (4 bytes in all 3 weathers of Starfield.esm: 0, 16, 0),
// CLDC is a link to a Clouds (CLDF) record (4 bytes, null in all 3),
// HNAM is the Volumetric Lighting struct: 8 links to VOLI, one per time of day (32 bytes in all 3; two hold
// BaseVL (02B710:Starfield.esm) or NewAtlantisVL49 (2574AE:Starfield.esm) in all 8 slots, one is all null).
// Each test reads a whole weather from Starfield.esm with both readers and writes it back byte for byte.
public class WeatherRawFieldTests
{
    private static IEnumerable<IWeatherGetter> Read(string hex)
        => ReadBoth<IWeatherGetter>(Record("WTHR", Hex(hex)), f => Weather.CreateFromBinary(f), (s, p) => WeatherBinaryOverlay.WeatherFactory(s, p));

    private static void WritesBack(IWeatherGetter weather, string hex)
    {
        var written = GameConstants.Starfield.MajorRecord(Write(w => weather.WriteToBinary(w)));
        written.Content.ToArray().ShouldBe(Hex(hex));
    }

    // SpaceWeather (249FA6:Starfield.esm)
    private const string Space = "";

    // NewAtlantisWeather50 (27CF9B:Starfield.esm)
    private const string NewAtlantis = "";

    [Fact]
    public void Space_MaxCloudLayersAndNullLinks()
    {
        foreach (var weather in Read(Space))
        {
            weather.EditorID.ShouldBe("SpaceWeather");
            weather.MaxCloudLayers.ShouldBe(16u);
            weather.CloudType.IsNull.ShouldBeTrue();
            var voli = weather.VolumetricLighting.ShouldNotBeNull();
            voli.Sunrise.IsNull.ShouldBeTrue();
            voli.LateSunset.IsNull.ShouldBeTrue();
            WritesBack(weather, Space);
        }
    }

    [Fact]
    public void NewAtlantis_VolumetricLightingLinks()
    {
        foreach (var weather in Read(NewAtlantis))
        {
            weather.EditorID.ShouldBe("NewAtlantisWeather50");
            weather.MaxCloudLayers.ShouldBe(0u);
            weather.CloudType.IsNull.ShouldBeTrue();
            var voli = weather.VolumetricLighting.ShouldNotBeNull();
            // NewAtlantisVL49 (2574AE:Starfield.esm) in all 8 slots
            foreach (var link in new[] { voli.Sunrise, voli.Day, voli.Sunset, voli.Night, voli.EarlySunrise, voli.LateSunrise, voli.EarlySunset, voli.LateSunset })
            {
                link.FormKey.ID.ShouldBe(0x2574AEu);
            }
            weather.EnumerateFormLinks().Select(l => l.FormKey.ID).Count(id => id == 0x2574AEu).ShouldBe(8);
            WritesBack(weather, NewAtlantis);
        }
    }
}
